integration/button.tsx.css:
@layer anm-global, anm-base, anm-variants, anm-compounds, anm-states, anm-system, anm-custom;

@layer anm-base {
  .animus-Button-f8490398 {
    border: none;
    border-radius: 4px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    line-height: calc(2px + 2.8ex + 2px);
    cursor: pointer;
  }
}

@layer anm-variants {
  @layer standalone, composed;
  @layer standalone {

  .animus-Button-f8490398--size-small {
    padding-left: 0.5rem;
    padding-right: 0.5rem;
    padding-top: 0.25rem;
    padding-bottom: 0.25rem;
    font-size: 0.875rem;
  }
  .animus-Button-f8490398--size-medium {
    padding-left: 1rem;
    padding-right: 1rem;
    padding-top: 0.5rem;
    padding-bottom: 0.5rem;
    font-size: 1rem;
  }
  .animus-Button-f8490398--size-large {
    padding-left: 1.5rem;
    padding-right: 1.5rem;
    padding-top: 1rem;
    padding-bottom: 1rem;
    font-size: 1.25rem;
  }
  .animus-Button-f8490398--intent-primary {
    background-color: var(--color-primary);
    --current-bg: var(--color-primary);
    color: var(--color-background);
  }
  .animus-Button-f8490398--intent-secondary {
    background-color: var(--color-secondary);
    --current-bg: var(--color-secondary);
    color: var(--color-background);
  }
  .animus-Button-f8490398--intent-danger {
    background-color: var(--color-secondary);
    --current-bg: var(--color-secondary);
    color: var(--color-background);
  }
  }
  @layer composed {
  }
}

@layer anm-states {
  .animus-Button-f8490398--hover {
    opacity: 0.9;
  }
  .animus-Button-f8490398--disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
}

