export const Compound = { Item };

export const MemberWrapped = createComponent(Compound.Item, 'animus-MemberWrapped-b520c131', {});

export const App = () => (
  <AssertedBox>
    <AssertedLink />
    <MemberWrapped />
  </AssertedBox>
);

